    ctx.fillStyle=COLOURS.muted;ctx.font='9px system-ui, sans-serif';ctx.fillText('TRAVEL PATH · TOP VIEW',x+10,y+16);
    var ox=x+iw*.25,oy=y+ih-17,sc=(ih-38)/42;
